{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "어린이집 옆 금연구역에 세운 차 안에서 창문을 열고 담배를 피우는 경우 과태료 부과 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "어린이집 옆이 제5조제1항에 따라 지정된 금연구역이라면, 그 금연구역 안에서는 차 안이라도 흡연을 해서는 안 된다. 제5조제4항은 ‘누구든지 제1항에 따라 지정된 금연구역에서 흡연을 해서는 아니된다’고 정하고, 제2조제2호는 흡연에 불이 붙은 담배를 소지하는 것도 포함한다고 규정한다. 따라서 창문을 열고 차 안에서 담배를 피우는 행위도 금연구역에서의 흡연에 해당할 수 있다. 이 경우 제10조제1항에 따라 시장은 그 위반자에게 10만원의 과태료를 부과·징수한다.",
          "b_ids": "금연:제5조제4항,금연:제2조제2호,금연:제10조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
